// -----------------------------------------
// BARBA HOOKS + INIT
// -----------------------------------------

barba.hooks.beforeEnter(data => {
  // Position new container on top
  gsap.set(data.next.container, {
    position: "fixed",
    top: 0,
    left: 0,
    right: 0,
  });

  if (lenis && typeof lenis.stop === "function") {
    lenis.stop();
  }

  initBeforeEnterFunctions(data.next.container);
  applyThemeFrom(data.next.container);
});

barba.hooks.afterLeave(data => {
  destroyBoxSequence();
  
  ScrollTrigger.getAll().forEach((trigger) => {
    const triggerEl = trigger.trigger;

    if (triggerEl && data.current.container.contains(triggerEl)) {
      trigger.kill();
    }
  });
});

/*
barba.hooks.afterLeave(() => {
  destroyBoxSequence();
  //destroyHeroSequence();

  //if (hasScrollTrigger) {
    //ScrollTrigger.getAll().forEach(trigger => trigger.kill());
  //}
  
  ScrollTrigger.getAll().forEach((trigger) => {
    const triggerEl = trigger.trigger;

    if (triggerEl && data.current.container.contains(triggerEl)) {
      trigger.kill();
    }
  });
});
*/

barba.hooks.enter(data => {
  initBarbaNavUpdate(data);
})

barba.hooks.afterEnter(data => {
  // Run page functions
  initAfterEnterFunctions(data.next.container);

  // Settle
  if (hasLenis) {
    lenis.resize();
    lenis.start();
  }

  if (hasScrollTrigger) {
    ScrollTrigger.refresh();
  }
});

barba.use(barbaPrefetch, {
  timeout: 2500,
  limit: 0
});

barba.init({
  debug: false, // Set to 'false' in production
  timeout: 7000,
  preventRunning: true,
  transitions: [
  {
    name: "self",
    sync: true,

    // First load
    async once(data) {
      const container = data?.next?.container || data?.current?.container || document.querySelector('[data-barba="container"]');
      initOnceFunctions();
      initBeforeEnterFunctions(container);
      const anim = runPageOnceAnimation(container);
      initAfterEnterFunctions(container);
      if (hasLenis && lenis) {
        lenis.resize();
        lenis.start();
      }
      if (hasScrollTrigger && window.ScrollTrigger) {
        ScrollTrigger.refresh();
      }
      return anim;
    },

    // Current page leaves
    async leave(data) {
      return runPageLeaveAnimation(data.current.container, data.next.container);
    },

    // New page enters
    async enter(data) {
      return runPageEnterAnimation(data.next.container);
    }
  },
  {
    name: "default",
    sync: true,

    // First load
    async once(data) {
      const container = data?.next?.container || data?.current?.container || document.querySelector('[data-barba="container"]');
      initOnceFunctions();
      initBeforeEnterFunctions(container);
      const anim = runPageOnceAnimation(container);
      initAfterEnterFunctions(container);
      if (hasLenis && lenis) {
        lenis.resize();
        lenis.start();
      }
      if (hasScrollTrigger && window.ScrollTrigger) {
        ScrollTrigger.refresh();
      }
      return anim;
    },

    // Current page leaves
    async leave(data) {
      return runPageLeaveAnimation(data.current.container, data.next.container);
    },

    // New page enters
    async enter(data) {
      return runPageEnterAnimation(data.next.container);
    }
  }],
});

// -----------------------------------------
// GENERIC + HELPERS
// -----------------------------------------

const themeConfig = {
  light: {
    nav: "dark",
    transition: "light"
  },
  dark: {
    nav: "light",
    transition: "dark"
  }
};

function applyThemeFrom(container) {
  const pageTheme = container?.dataset?.pageTheme || "light";
  const config = themeConfig[pageTheme] || themeConfig.light;

  document.body.dataset.pageTheme = pageTheme;
  const transitionEl = document.querySelector('[data-theme-transition]');
  if (transitionEl) {
    transitionEl.dataset.themeTransition = config.transition;
  }

  const nav = document.querySelector('[data-theme-nav]');
  if (nav) {
    nav.dataset.themeNav = config.nav;
  }
}

function initLenis() {
  if (lenis) return; // already created
  if (!hasLenis) return;

  lenis = new Lenis({
    //lerp: 0.18,
    lerp: 0.2,
    autoRaf: true,
    anchors: true,
    //wheelMultiplier: 1.25,
  });

  if (hasScrollTrigger) {
    lenis.on("scroll", ScrollTrigger.update);
  }

  //gsap.ticker.add((time) => {
  //lenis.raf(time * 1000);
  //});

  //gsap.ticker.lagSmoothing(0);
}

function resetPage(container) {
  window.scrollTo(0, 0);
  gsap.set(container, { clearProps: "position,top,left,right" });

  if (hasLenis) {
    lenis.resize();
    lenis.start();
  }
}

function debounceOnWidthChange(fn, ms) {
  let last = innerWidth,
    timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      if (innerWidth !== last) {
        last = innerWidth;
        fn.apply(this, args);
      }
    }, ms);
  };
}

function initBarbaNavUpdate(data) {
  var tpl = document.createElement('template');
  tpl.innerHTML = data.next.html.trim();
  var nextNodes = tpl.content.querySelectorAll('[data-barba-update]');
  var currentNodes = document.querySelectorAll('nav [data-barba-update]');

  currentNodes.forEach(function (curr, index) {
    var next = nextNodes[index];
    if (!next) return;

    // Aria-current sync
    var newStatus = next.getAttribute('aria-current');
    if (newStatus !== null) {
      curr.setAttribute('aria-current', newStatus);
    } else {
      curr.removeAttribute('aria-current');
    }

    // Class list sync
    var newClassList = next.getAttribute('class') || '';
    curr.setAttribute('class', newClassList);
  });
}

function scrollToInitialHash(container = document) {
  const hash = window.location.hash;
  if (!hash || hash === "#") return;
  const target = container.querySelector(hash) || document.querySelector(hash);
  if (!target) return;
  // Reduced motion: jump
  if (reducedMotion) {
    target.scrollIntoView();
    return;
  }
  // Smooth: Lenis if available, else native smooth
  if (hasLenis && lenis) {
    lenis.scrollTo(target, {
      offset: 0,
      duration: 1,
      immediate: false,
      lock: true,
    });
  } else {
    target.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

