function initSearch() {
  const element = nextPage.querySelector("[data-search]");
  if (!element) return;

  const searchInput = element.querySelector("[data-search-form]");
  const searchButton = element.querySelector("[data-search-form-button]");
  const loadMoreButton = element.querySelector("[data-search-load-more]");
  const loadMoreButtonText = loadMoreButton?.querySelector("[data-search-load-more-text]");
  
  const emptyState = element.querySelector("[data-search-empty]");
  const emptyLoadMoreState = element.querySelector("[data-search-empty-load-more]");

  const filterButtons = element.querySelectorAll("[data-search-filter-button]");

  // Set this attribute on the Webflow Collection List Wrapper:
  // <div data-search-load-list class="books-list__collection w-dyn-list">
  const collection = element.querySelector("[data-search-load-list]");
  const list = collection?.querySelector(".w-dyn-items");

  const activeTags = new Set();

  let activeSearchIds = null;
  let bookData = [];
  let miniSearch = null;

  let nextPageUrl = getNextPageUrl(collection);
  let isLoadingMore = false;

  function normalize(value) {
    return value.trim().toLowerCase();
  }

  function getBooks() {
    return [...element.querySelectorAll("[data-search-target-book]")];
  }

  function getNextPageUrl(scope) {
    const nextLink = scope?.querySelector(".w-pagination-next");
    if (!nextLink) return null;

    const href = nextLink.getAttribute("href");
    if (!href) return null;

    return new URL(href, window.location.href).href;
  }

  function getPaginationParamFromHref(href) {
    if (!href) return null;

    const match = href.match(/[?&]([^=]+_page)=\d+/);
    return match ? match[1] : null;
  }

  function getNextCollection(doc) {
    const currentNextHref = collection
      ?.querySelector(".w-pagination-next")
      ?.getAttribute("href");

    const paginationParam = getPaginationParamFromHref(currentNextHref);

    if (paginationParam) {
      const collections = [...doc.querySelectorAll(".w-dyn-list")];

      const matchedCollection = collections.find((dynList) => {
        const nextHref = dynList
          .querySelector(".w-pagination-next")
          ?.getAttribute("href");

        const prevHref = dynList
          .querySelector(".w-pagination-previous")
          ?.getAttribute("href");

        return (
          nextHref?.includes(`${paginationParam}=`) ||
          prevHref?.includes(`${paginationParam}=`)
        );
      });

      if (matchedCollection) return matchedCollection;
    }

    return doc.querySelector("[data-search-load-list]");
  }

  function rebuildIndex() {
    const books = getBooks();

    bookData = books.map((book, index) => {
      const tags = [...book.querySelectorAll("[data-search-target-book-genre]")]
        .map((genre) => genre.getAttribute("data-search-target-book-genre"))
        .filter(Boolean)
        .map(normalize);

      const title =
        book.querySelector("[data-search-target-book-title]")?.textContent || "";

      return {
        id: String(index),
        element: book,
        tags,
        title,
      };
    });

    miniSearch = new MiniSearch({
      fields: ["title"],
      storeFields: ["id"],
      searchOptions: {
        prefix: true,
        fuzzy: 0.2,
        combineWith: "AND",
      },
    });

    miniSearch.addAll(bookData);
  }

  function updateSearch() {
    if (!searchInput || !miniSearch) return;

    const query = searchInput.value.trim();

    if (!query) {
      activeSearchIds = null;
    } else {
      const results = miniSearch.search(query);
      activeSearchIds = new Set(results.map((result) => result.id));
    }

    update();
  }

  function update() {
    let visibleCount = 0;
  
    bookData.forEach((book) => {
      const matchesTags =
        activeTags.size === 0 ||
        [...activeTags].every((tag) => book.tags.includes(tag));
  
      const matchesSearch =
        activeSearchIds === null || activeSearchIds.has(book.id);
  
      const isVisible = matchesTags && matchesSearch;
  
      book.element.style.display = isVisible ? "" : "none";
  
      if (isVisible) visibleCount++;
    });
  
    const hasActiveFilterOrSearch =
      activeTags.size > 0 || !!searchInput?.value.trim();
  
    if (emptyState) {
      emptyState.style.display =
        visibleCount === 0 && !nextPageUrl ? "" : "none";
    }
  
    if (emptyLoadMoreState) {
      emptyLoadMoreState.style.display =
        visibleCount === 0 && nextPageUrl && hasActiveFilterOrSearch ? "" : "none";
    }
  
    hideEmptyGroups();
    updateLoadMoreButton();
  
    requestAnimationFrame(() => {
      rebuildBookSliders();
      ScrollTrigger.refresh();
    });
  }

  function hideEmptyGroups() {
    const groups = element.querySelectorAll("[data-search-target-item]");

    groups.forEach((group) => {
      const visibleBooks = [...group.querySelectorAll("[data-search-target-book]")]
        .some((book) => book.style.display !== "none");

      group.style.display = visibleBooks ? "" : "none";
    });
  }

  function updateLoadMoreButton() {
    if (!loadMoreButton) return;
  
    const hasActiveFilterOrSearch =
      activeTags.size > 0 || !!searchInput?.value.trim();
  
    const hasVisibleBooks = bookData.some(
      (book) => book.element.style.display !== "none"
    );
  
    loadMoreButton.style.display = nextPageUrl ? "" : "none";
    loadMoreButton.disabled = isLoadingMore;
  
    if (loadMoreButtonText) {
      if (isLoadingMore) {
        loadMoreButtonText.textContent = "Loading...";
      } else if (hasActiveFilterOrSearch && !hasVisibleBooks) {
        loadMoreButtonText.textContent = "Load more results";
      } else {
        loadMoreButtonText.textContent = "Load more";
      }
    }
  }

  async function loadMore() {
    if (!nextPageUrl || isLoadingMore || !list) return;

    isLoadingMore = true;
    updateLoadMoreButton();

    try {
      const response = await fetch(nextPageUrl);
      if (!response.ok) throw new Error("Could not load next page");

      const html = await response.text();
      const nextDoc = new DOMParser().parseFromString(html, "text/html");

      const nextCollection = getNextCollection(nextDoc);
      if (!nextCollection) throw new Error("Next collection not found");

      const nextList = nextCollection.querySelector(".w-dyn-items");
      if (!nextList) throw new Error("Next list not found");

      const nextItems = [...nextList.children];

      nextItems.forEach((item) => {
        list.appendChild(item);
      });

      nextPageUrl = getNextPageUrl(nextCollection);

      rebuildIndex();

      if (searchInput?.value.trim()) {
        updateSearch();
      } else {
        update();
      }
    } catch (error) {
      console.error(error);
    } finally {
      isLoadingMore = false;
      updateLoadMoreButton();
    }
  }

  filterButtons.forEach((button) => {
    button.setAttribute("aria-pressed", "false");

    button.addEventListener("click", () => {
      const tag = button.getAttribute("data-search-filter-tag");
      if (!tag) return;

      const normalizedTag = normalize(tag);

      if (activeTags.has(normalizedTag)) {
        activeTags.delete(normalizedTag);
        button.classList.remove("is--active");
        button.setAttribute("aria-pressed", "false");
      } else {
        activeTags.add(normalizedTag);
        button.classList.add("is--active");
        button.setAttribute("aria-pressed", "true");
      }

      update();
    });
  });

  if (searchInput) {
    searchInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        updateSearch();
      }
    });
  }

  if (searchButton) {
    searchButton.addEventListener("click", updateSearch);
  }

  if (loadMoreButton) {
    loadMoreButton.addEventListener("click", loadMore);
  }

  rebuildIndex();
  update();
}

function initScrollingCta() {
  const element = nextPage.querySelector("[data-scrolling-cta]");

  if (!element) return;

  const target = element.querySelector("[data-scrolling-cta-item]");
  const trigger = nextPage.querySelector("[data-scrolling-cta-trigger]");

  if (!target || !trigger) return;

  gsap.to(target, {
    y: "12em",
    duration: 0.8,
    ease: "energy",
    easeReverse: true,
    scrollTrigger: {
      trigger: trigger,
      start: "top 80%", // trigger kommt unten in den Viewport
      end: "bottom bottom",
      toggleActions: "play none none reverse",
    },
  });
}

function killChildTweensOf(ancestor) {
  ancestor = gsap.utils.toArray(ancestor)[0];
  gsap.globalTimeline
    .getChildren(true, true, false)
    .forEach((tween) =>
      tween
      .targets()
      .forEach((e) => e.nodeType && ancestor.contains(e) && tween.kill(e))
    )
}

function initTabs() {
  const elements = nextPage.querySelectorAll("[data-tabs]");

  if (elements.length === 0) return;

  elements.forEach((element) => {
    const tabs = Array.from(element.querySelectorAll("[data-tabs-tab]"));
    const tabPanels = Array.from(element.querySelectorAll("[data-tabs-panel]"));
    const panels = [];
    let firstTab = null;
    let lastTab = null;
    let activeIndex = -1;

    const ACTIVE_CLASS = "is--active";
    const HIDDEN_CLASS = "is--hidden";
    const INVIEW_CLASS = "is--inview";

    if (tabs.length === 0) return;

    function initContainerTabs() {
      for (let i = 0; i < tabs.length; i += 1) {
        const $tab = tabs[i];

        $tab.tabIndex = -1;
        $tab.setAttribute("aria-selected", "false");

        let controls = $tab.getAttribute("aria-controls");
        let $tabpanel = null;

        if (controls) {
          $tabpanel = element.querySelector(`#${controls}`);
        }

        if (!$tabpanel) {
          $tabpanel = tabPanels[i] || null;

          if ($tabpanel) {
            if (!$tabpanel.id) {
              const randomId = `tabs-panel-${Math.random().toString(36).slice(2, 9)}`;
              $tabpanel.id = randomId;
            }

            $tab.setAttribute("aria-controls", $tabpanel.id);
          }
        }

        panels.push($tabpanel || null);

        if (!firstTab) {
          firstTab = $tab;
        }
        lastTab = $tab;
      }

      if (activeIndex === -1 && firstTab) {
        activeIndex = 0;
      }
    }

    function setSelectedTab($currentTab) {
      const DIR_CLASSES = ["is-entering-from-right", "is-entering-from-left",
        "is-leaving-to-right", "is-leaving-to-left"
      ];

      const currentIndex = tabs.indexOf($currentTab);
      if (currentIndex === -1) return;

      const previousIndex = activeIndex;
      let direction = null;

      if (previousIndex !== -1 && previousIndex !== currentIndex) {
        direction = currentIndex > previousIndex ? "forward" : "backward";
      }

      for (let i = 0; i < tabs.length; i += 1) {
        const $tab = tabs[i];
        const $panel = panels[i];
        if (!$panel) continue;

        $panel.classList.remove(...DIR_CLASSES);

        if (i === currentIndex) {
          $tab.setAttribute("aria-selected", "true");
          $tab.classList.add(ACTIVE_CLASS);
          $tab.removeAttribute("tabindex");
          $panel.classList.remove("is-leaving-to-left", "is-leaving-to-right");
          $panel.classList.remove(HIDDEN_CLASS);
          $panel.hidden = false;
          $panel.tabIndex = 0;

          if (direction === "forward") {
            $panel.classList.add("is-entering-from-right");
          } else if (direction === "backward") {
            $panel.classList.add("is-entering-from-left");
          }

          requestAnimationFrame(() => {
            $panel.classList.add(ACTIVE_CLASS);
            requestAnimationFrame(() => {
              $panel.classList.add(INVIEW_CLASS);
            });
          });
        } else {
          $tab.setAttribute("aria-selected", "false");
          $tab.classList.remove(ACTIVE_CLASS);
          $tab.tabIndex = -1;

          if (i === previousIndex && direction) {
            const leaveClass = direction === "forward" ? "is-leaving-to-left" :
              "is-leaving-to-right";

            $panel.hidden = false;
            $panel.classList.remove(ACTIVE_CLASS, INVIEW_CLASS);
            $panel.classList.add(leaveClass);

            const onAnimEnd = (event) => {
              if (event.target !== $panel) return;

              if (!$panel.classList.contains(leaveClass)) {
                $panel.removeEventListener("animationend", onAnimEnd);
                return;
              }

              $panel.classList.add(HIDDEN_CLASS);
              $panel.hidden = true;
              $panel.tabIndex = -1;
              $panel.classList.remove(leaveClass);
              $panel.removeEventListener("animationend", onAnimEnd);
            };

            $panel.addEventListener("animationend", onAnimEnd);
          } else {
            $panel.classList.add(HIDDEN_CLASS);
            $panel.classList.remove(ACTIVE_CLASS, INVIEW_CLASS);
            $panel.hidden = true;
            $panel.tabIndex = -1;
          }
        }
      }

      activeIndex = currentIndex;
    }

    function moveFocusToTab($tab) {
      if ($tab) {
        $tab.focus();
      }
    }

    function moveFocusToPreviousTab($currentTab) {
      if ($currentTab === firstTab) {
        moveFocusToTab(lastTab);
      } else {
        const index = tabs.indexOf($currentTab);
        if (index > 0) {
          moveFocusToTab(tabs[index - 1]);
        }
      }
    }

    function moveFocusToNextTab($currentTab) {
      if ($currentTab === lastTab) {
        moveFocusToTab(firstTab);
      } else {
        const index = tabs.indexOf($currentTab);
        if (index > -1 && index < tabs.length - 1) {
          moveFocusToTab(tabs[index + 1]);
        }
      }
    }

    function onKeydown(event) {
      const $target = event.currentTarget;
      let flag = false;

      switch (event.key) {
      case "ArrowLeft":
        moveFocusToPreviousTab($target);
        flag = true;
        break;

      case "ArrowRight":
        moveFocusToNextTab($target);
        flag = true;
        break;

      case "Home":
        moveFocusToTab(firstTab);
        flag = true;
        break;

      case "End":
        moveFocusToTab(lastTab);
        flag = true;
        break;

      default:
        break;
      }

      if (flag) {
        event.stopPropagation();
        event.preventDefault();
      }
    }

    function onClick(event) {
      setSelectedTab(event.currentTarget);
    }

    function bindEvents() {
      for (let i = 0; i < tabs.length; i += 1) {
        const $tab = tabs[i];
        $tab.addEventListener("keydown", onKeydown);
        $tab.addEventListener("click", onClick);
      }
    }

    initContainerTabs();
    if (firstTab) {
      setSelectedTab(firstTab);
    }
    bindEvents();
  });
}

function initEmojiRain() {
  const elements = nextPage.querySelectorAll("[data-emoji-rain]");
  const mm = gsap.matchMedia();

  elements.forEach((element) => {
    const emojiContainer = document.querySelector("[data-emoji-rain-container]");

    if (!emojiContainer) return;

    let emojiAnimationRunning = false;
    let cleanupTimeout;

    const createRain = (emojiTypes) => {
      if (emojiAnimationRunning) return;

      emojiAnimationRunning = true;

      const emojiContainerHeight = emojiContainer.offsetHeight;
      const emojiQuantity = 40;
      const createdElements = [];

      const getRandomInt = (min, max) =>
        Math.floor(Math.random() * (max - min + 1)) + min;

      const createEmojiElement = () => {
        const emojiScale = Math.random() * 0.7 + 0.4;
        const emojiRotate = getRandomInt(-28, 28);
        const emojiDelay = 0.001 * getRandomInt(0, 1250);
        const emojiSpeed = getRandomInt(800, 1800) * 0.001;
        const emojiPosition = `${getRandomInt(0, 10)}0%`;
        const emojiClass = `choice__single-rain-emoji-image-${
          emojiTypes[Math.floor(Math.random() * emojiTypes.length)]
        }`;

        const singleEmoji = document.createElement("div");
        singleEmoji.className = "choice__single-rain-emoji is--append";
        singleEmoji.style.left = emojiPosition;

        const singleEmojiChild = document.createElement("div");
        singleEmojiChild.className = emojiClass;
        singleEmoji.appendChild(singleEmojiChild);

        emojiContainer.appendChild(singleEmoji);
        createdElements.push(singleEmoji);

        gsap.fromTo(
          singleEmoji,
          {
            y: emojiContainerHeight,
            xPercent: -50,
            rotate: 0.001,
            scale: emojiScale,
          },
          {
            y: "-110%",
            xPercent: -50,
            rotate: 0.001,
            delay: emojiDelay,
            ease: "power1.in",
            duration: emojiSpeed,
          }
        );

        gsap.fromTo(
          singleEmojiChild,
          {
            xPercent: -25,
            rotate: emojiRotate,
          },
          {
            xPercent: 25,
            rotate: -emojiRotate,
            ease: "power1.inOut",
            delay: emojiDelay,
            duration: 0.8,
            repeat: -1,
            yoyo: true,
          }
        );
      };

      Array.from({ length: emojiQuantity }).forEach(createEmojiElement);

      cleanupTimeout = setTimeout(() => {
        createdElements.forEach((el) => el.remove());
        emojiAnimationRunning = false;
      }, 2750);
    };

    mm.add(
      {
        motion: "(prefers-reduced-motion: no-preference)",
      },
      (context) => {
        const { motion } = context.conditions;

        if (!motion) return;

        const type1 = element.getAttribute("data-emoji-rain-type-1");
        const type2 = element.getAttribute("data-emoji-rain-type-2") || type1;

        const trigger = ScrollTrigger.create({
          trigger: element,
          start: "top 80%",
          onEnter: (self) => {
            if (self.direction === 1) {
              createRain([type1, type2]);
            }
          },
        });

        return () => {
          trigger.kill();
          clearTimeout(cleanupTimeout);
          gsap.killTweensOf(emojiContainer.querySelectorAll(
            ".choice__single-rain-emoji, .choice__single-rain-emoji > div"));
          emojiContainer
            .querySelectorAll(".choice__single-rain-emoji.is--append")
            .forEach((el) => el.remove());
          emojiAnimationRunning = false;
        };
      }
    );
  });
}

function initPlopIn() {
  const elements = nextPage.querySelectorAll("[data-plop-in]");
  const mm = gsap.matchMedia();

  elements.forEach((element) => {
    const item = element.querySelector("[data-plop-in-item]");

    if (!item) return;

    mm.add(
      {
        motion: "(prefers-reduced-motion: no-preference)",
        mobile: "(max-width: 990px)",
      },
      (context) => {
        const { motion, mobile } = context.conditions;

        if (!motion) return;

        gsap.set(item, {
          scale: 0,
          rotate: -20,
          y: "-4em",
        });

        const tl = gsap.timeline({ paused: true });

        tl.to(
          item,
          {
            scale: 1,
            y: "0em",
            rotate: 11,
            duration: 0.7,
            ease: "elastic.out(1, 0.72)",
          }
        )

        const trigger = ScrollTrigger.create({
          trigger: element,
          start: "top 80%",
          end: "bottom top",
          onEnter: () => tl.play(),
        });

        return () => {
          trigger.kill();
          tl.kill();
        };
      }
    );
  });
}

let boxSequenceDestroyFns = [];

function destroyBoxSequence() {
  boxSequenceDestroyFns.forEach((fn) => fn());
  boxSequenceDestroyFns = [];
}

function initBoxSequence() {
  boxSequenceDestroyFns = [];

  const wraps = nextPage.querySelectorAll('[data-box-sequence]');

  wraps.forEach((wrap) => {
    if (wrap.dataset.sequenceInit === 'true') return;
    wrap.dataset.sequenceInit = 'true';

    let isDestroyed = false;

    const element = wrap.querySelector('[data-box-sequence-element]');
    const canvas = element && element.querySelector('[data-box-sequence-canvas]');
    const finalText = wrap.querySelector('[data-box-sequence-text-final]');
    const buttons = wrap.querySelectorAll('[data-box-sequence-button]');

    if (!element || !canvas) return;

    const startTrigger = 'top top';
    const endTrigger = 'bottom bottom';
    const ctx = canvas.getContext('2d');

    let currentProgress = 0;
    let isTicking = false;
    let cachedWidth = 0;
    let cachedHeight = 0;
    let resizeTimer;

    function resizeCanvas() {
      const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
      const width = element.clientWidth;
      const height = element.clientHeight;

      if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        canvas.style.width = width + 'px';
        canvas.style.height = height + 'px';
        cachedWidth = width * dpr;
        cachedHeight = height * dpr;
      }
    }

    function scheduleRender() {
      if (!isTicking && !isDestroyed) {
        isTicking = true;
        requestAnimationFrame(() => {
          renderSignalDeconstruction(currentProgress);
          isTicking = false;
        });
      }
    }

    function renderSignalDeconstruction(p) {
      if (isDestroyed || !ctx) return;

      const cw = cachedWidth || canvas.width;
      const ch = cachedHeight || canvas.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 1.5);

      ctx.clearRect(0, 0, cw, ch);

      if (p < -0.05 || p > 1.05) return;

      // Adaptive sizing: generous mobile scale with vertical flow
      const isMob = cw < 650 * dpr;
      const s = isMob 
        ? (cw / (420 * dpr)) * dpr 
        : Math.min(cw / (1050 * dpr), ch / (820 * dpr)) * dpr;
      const cx = cw / 2;
      const cy = ch / 2 + 10 * s;
      const rw = isMob ? Math.min(cw * 0.88, 320 * s) : 320 * s;
      const rh = isMob ? Math.min(ch * 0.65, 480 * s) : 490 * s;

      const clamp = (v, min, max) => Math.min(Math.max(v, min), max);
      const ease = (t) => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;

      // Ambient radial glow
      const glow = ctx.createRadialGradient(cx, cy, 30 * s, cx, cy, 420 * s);
      glow.addColorStop(0, 'rgba(98, 87, 255, 0.15)');
      glow.addColorStop(1, 'rgba(9, 9, 11, 0)');
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, cw, ch);

      // Section Top HUD
      ctx.save();
      ctx.fillStyle = '#C6FF4A';
      ctx.font = '600 ' + (11 * s) + 'px "IBM Plex Mono", monospace';
      ctx.textAlign = 'center';
      ctx.fillText('[VIRALYST ENGINE: MULTIMODAL SHORT-FORM DECONSTRUCTION]', cx, 40 * s);
      ctx.restore();

      // STATE 01 & 02: p < 0.20 -> Reel Enters, Plays & Freezes
      if (p < 0.20) {
        ctx.save();
        ctx.beginPath();
        ctx.ellipse(cx, cy + rh / 2 + 20 * s, rw * 0.44, 14 * s, 0, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
        ctx.fill();
        ctx.restore();

        drawReelSolid(cx, cy, rw, rh, s, p);

        if (p > 0.10) {
          const scanProgress = (p - 0.10) / 0.10;
          const scanY = cy - rh / 2 + (rh * scanProgress);
          ctx.save();
          ctx.strokeStyle = '#2997FF';
          ctx.lineWidth = 3.5 * s;
          ctx.shadowColor = '#2997FF';
          ctx.shadowBlur = 12 * s;
          ctx.beginPath();
          ctx.moveTo(cx - rw / 2 + 15 * s, scanY);
          ctx.lineTo(cx + rw / 2 - 15 * s, scanY);
          ctx.stroke();
          ctx.restore();
        }
      }
      // STATE 03 - 07: 0.20 <= p < 0.68 -> 5-Layer Adaptive Separation
      else if (p < 0.68) {
        const factor = ease(clamp((p - 0.18) / 0.35, 0, 1));
        const reorg = clamp((p - 0.52) / 0.16, 0, 1);

        let hkW, hkH, hkX, hkY;
        let sbW, sbH, sbX, sbY;
        let capW, capH, capX, capY;
        let auW, auH, auX, auY;
        let tmW, tmH, tmX, tmY;

        if (isMob) {
          // Vertical cascading stack on mobile
          hkW = Math.min(cw * 0.90, 340 * s);
          hkH = 50 * s;
          hkX = cx;
          hkY = cy - 180 * s * factor;

          sbW = Math.min(cw * 0.90, 340 * s);
          sbH = 95 * s;
          sbX = cx;
          sbY = cy - 85 * s * factor;

          capW = Math.min(cw * 0.90, 340 * s);
          capH = 44 * s;
          capX = cx;
          capY = cy + 5 * s * factor;

          auW = Math.min(cw * 0.90, 340 * s);
          auH = 95 * s;
          auX = cx;
          auY = cy + 95 * s * factor;

          tmW = Math.min(cw * 0.90, 340 * s);
          tmH = 50 * s;
          tmX = cx;
          tmY = cy + 185 * s * factor;
        } else {
          // Desktop Cruciform Constellation
          hkW = 340 * s;
          hkH = 62 * s;
          hkX = cx;
          hkY = cy - (185 * s * factor) + (20 * s * reorg);

          sbW = 220 * s;
          sbH = 260 * s;
          sbX = cx - (195 * s * factor) + (20 * s * reorg);
          sbY = cy + (10 * s * factor);

          capW = 260 * s;
          capH = 46 * s;
          capX = cx;
          capY = cy + (12 * s * factor) - (10 * s * reorg);

          auW = 220 * s;
          auH = 260 * s;
          auX = cx + (195 * s * factor) - (20 * s * reorg);
          auY = cy + (10 * s * factor);

          tmW = 340 * s;
          tmH = 64 * s;
          tmX = cx;
          tmY = cy + (200 * s * factor) - (15 * s * reorg);
        }

        drawHookLayer(hkX, hkY, hkW, hkH, s, factor);
        drawVisualLayer(sbX, sbY, sbW, sbH, s, factor);
        drawCaptionLayer(capX, capY, capW, capH, s, factor);
        drawAudioLayer(auX, auY, auW, auH, s, factor);
        drawEditLayer(tmX, tmY, tmW, tmH, s, factor);

        // Laser Connection Traces connecting all 5 layers
        if (factor > 0.3) {
          ctx.save();
          ctx.setLineDash([4 * s, 4 * s]);
          ctx.strokeStyle = 'rgba(41, 151, 255, ' + (0.55 * factor) + ')';
          ctx.lineWidth = 1.5 * s;
          ctx.beginPath();
          ctx.moveTo(hkX, hkY + hkH / 2);
          ctx.lineTo(sbX + sbW / 2, sbY);
          ctx.lineTo(capX, capY);
          ctx.lineTo(auX - auW / 2, auY);
          ctx.lineTo(tmX, tmY - tmH / 2);
          ctx.stroke();
          ctx.restore();
        }
      }
      // STATE 08 & 09: p >= 0.68 -> Assembled Content Direction Blueprint
      else {
        const assem = ease(clamp((p - 0.68) / 0.16, 0, 1));
        drawContentDirection(cx, cy + 15 * s, rw * 1.12, rh * 0.86, s, assem);
      }
    }

    function drawReelSolid(x, y, w, h, s, progress) {
      ctx.save();
      ctx.translate(x, y);

      roundRect(ctx, -w / 2, -h / 2, w, h, 26 * s);
      ctx.fillStyle = '#09090B';
      ctx.fill();
      ctx.strokeStyle = '#F3F0E9';
      ctx.lineWidth = 3.5 * s;
      ctx.stroke();

      const vw = w - 24 * s;
      const vh = h * 0.65;
      roundRect(ctx, -vw / 2, -h / 2 + 12 * s, vw, vh, 18 * s);
      ctx.fillStyle = '#141824';
      ctx.fill();

      // Camera recording HUD
      ctx.fillStyle = '#FF3B45';
      ctx.beginPath();
      ctx.arc(-vw / 2 + 25 * s, -h / 2 + 30 * s, 5 * s, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#F3F0E9';
      ctx.font = '600 ' + (11 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('REC 00:02:18 • 60FPS', -vw / 2 + 38 * s, -h / 2 + 34 * s);

      // Hook overlay
      roundRect(ctx, -vw / 2 + 12 * s, -h / 2 + 55 * s, vw - 24 * s, 58 * s, 10 * s);
      ctx.fillStyle = 'rgba(9, 9, 11, 0.9)';
      ctx.fill();
      ctx.strokeStyle = '#FF3B45';
      ctx.lineWidth = 2 * s;
      ctx.stroke();

      ctx.fillStyle = '#FF3B45';
      ctx.font = '700 ' + (12 * s) + 'px "Bricolage Grotesque", sans-serif';
      ctx.fillText('[HOOK: CONTRARIAN OPEN]', -vw / 2 + 24 * s, -h / 2 + 78 * s);
      ctx.fillStyle = '#F3F0E9';
      ctx.font = (12 * s) + 'px "Instrument Sans", sans-serif';
      ctx.fillText('Why 99% of short-form hooks fail in 2s', -vw / 2 + 24 * s, -h / 2 + 98 * s);

      // Waveform
      for (let i = 0; i < 18; i++) {
        const bh = (16 + 55 * Math.sin(i * 0.48) ** 2) * s;
        const bx = -vw / 2 + 30 * s + i * 14 * s;
        roundRect(ctx, bx, -h / 2 + 205 * s - bh / 2, 6 * s, bh, 2.5 * s);
        ctx.fillStyle = '#2997FF';
        ctx.fill();
      }

      // Bottom Scrubber
      const sy = -h / 2 + vh - 16 * s;
      ctx.strokeStyle = '#404555';
      ctx.lineWidth = 3.5 * s;
      ctx.beginPath();
      ctx.moveTo(-vw / 2 + 16 * s, sy);
      ctx.lineTo(vw / 2 - 16 * s, sy);
      ctx.stroke();

      ctx.strokeStyle = '#C6FF4A';
      ctx.beginPath();
      ctx.moveTo(-vw / 2 + 16 * s, sy);
      ctx.lineTo(-vw / 2 + 150 * s, sy);
      ctx.stroke();

      // Lower brief info
      const bw = w - 24 * s;
      const bh = h - vh - 36 * s;
      roundRect(ctx, -bw / 2, h / 2 - bh - 12 * s, bw, bh, 16 * s);
      ctx.fillStyle = '#F3F0E9';
      ctx.fill();

      ctx.fillStyle = '#09090B';
      ctx.font = '700 ' + (14 * s) + 'px "Bricolage Grotesque", sans-serif';
      ctx.fillText('SIGNAL CORE ARCHETYPE', -bw / 2 + 16 * s, h / 2 - bh + 22 * s);

      ctx.fillStyle = '#555560';
      ctx.font = (12 * s) + 'px "Instrument Sans", sans-serif';
      ctx.fillText('Analyzing Visual • Hook • Captions • Cadence', -bw / 2 + 16 * s, h / 2 - bh + 44 * s);
      ctx.restore();
    }

    function drawHookLayer(x, y, w, h, s, f) {
      ctx.save();
      ctx.translate(x, y);
      ctx.shadowColor = 'rgba(255, 59, 69, 0.35)';
      ctx.shadowBlur = 14 * s * f;

      roundRect(ctx, -w / 2, -h / 2, w, h, 14 * s);
      ctx.fillStyle = '#09090B';
      ctx.fill();
      ctx.strokeStyle = '#FF3B45';
      ctx.lineWidth = 2.5 * s;
      ctx.stroke();

      ctx.fillStyle = '#FF3B45';
      ctx.font = '700 ' + (11 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('[01 / HOOK SCRIPT]', -w / 2 + 16 * s, -h / 2 + 24 * s);

      ctx.fillStyle = '#F3F0E9';
      ctx.font = '600 ' + (13 * s) + 'px "Bricolage Grotesque", sans-serif';
      ctx.fillText('"Stop writing hooks like it is 2023."', -w / 2 + 16 * s, -h / 2 + 46 * s);
      ctx.restore();
    }

    function drawVisualLayer(x, y, w, h, s, f) {
      ctx.save();
      ctx.translate(x, y);
      ctx.shadowColor = 'rgba(98, 87, 255, 0.3)';
      ctx.shadowBlur = 16 * s * f;

      roundRect(ctx, -w / 2, -h / 2, w, h, 16 * s);
      ctx.fillStyle = '#141826';
      ctx.fill();
      ctx.strokeStyle = '#6257FF';
      ctx.lineWidth = 2.5 * s;
      ctx.stroke();

      ctx.fillStyle = '#6257FF';
      ctx.font = '700 ' + (11 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('[02 / VISUAL CUES]', -w / 2 + 16 * s, -h / 2 + 24 * s);

      const ph = (h - 55 * s) / 3;
      const panels = [
        { t: '00:00 - THE INTERRUPT', c: '#FF3B45' },
        { t: '00:01 - TACTILE PROOF', c: '#2997FF' },
        { t: '00:03 - CONTEXT PIVOT', c: '#C6FF4A' }
      ];
      for (let i = 0; i < 3; i++) {
        const py = -h / 2 + 38 * s + i * (ph + 5 * s);
        roundRect(ctx, -w / 2 + 12 * s, py, w - 24 * s, ph, 8 * s);
        ctx.fillStyle = '#0B0E17';
        ctx.fill();
        ctx.strokeStyle = panels[i].c;
        ctx.lineWidth = 1.2 * s;
        ctx.stroke();

        ctx.fillStyle = panels[i].c;
        ctx.font = '600 ' + (10 * s) + 'px "IBM Plex Mono", monospace';
        ctx.fillText(panels[i].t, -w / 2 + 18 * s, py + ph / 2 + 4 * s);
      }
      ctx.restore();
    }

    function drawCaptionLayer(x, y, w, h, s, f) {
      ctx.save();
      ctx.translate(x, y);
      ctx.shadowColor = 'rgba(255, 40, 120, 0.35)';
      ctx.shadowBlur = 14 * s * f;

      roundRect(ctx, -w / 2, -h / 2, w, h, 12 * s);
      ctx.fillStyle = 'rgba(15, 12, 22, 0.95)';
      ctx.fill();
      ctx.strokeStyle = '#FF2878';
      ctx.lineWidth = 2 * s;
      ctx.stroke();

      ctx.fillStyle = '#FF2878';
      ctx.font = '600 ' + (10 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('[03 / KINETIC CAPTIONS]', -w / 2 + 14 * s, -h / 2 + 18 * s);

      ctx.fillStyle = '#F3F0E9';
      ctx.font = '500 ' + (12 * s) + 'px "Instrument Sans", sans-serif';
      ctx.fillText('Dynamic word-by-word reveal aligned to speech', -w / 2 + 14 * s, -h / 2 + 36 * s);
      ctx.restore();
    }

    function drawAudioLayer(x, y, w, h, s, f) {
      ctx.save();
      ctx.translate(x, y);
      ctx.shadowColor = 'rgba(41, 151, 255, 0.3)';
      ctx.shadowBlur = 16 * s * f;

      roundRect(ctx, -w / 2, -h / 2, w, h, 16 * s);
      ctx.fillStyle = '#111422';
      ctx.fill();
      ctx.strokeStyle = '#2997FF';
      ctx.lineWidth = 2.5 * s;
      ctx.stroke();

      ctx.fillStyle = '#2997FF';
      ctx.font = '700 ' + (11 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('[04 / AUDIO FREQUENCY]', -w / 2 + 16 * s, -h / 2 + 24 * s);

      ctx.fillStyle = '#8590A8';
      ctx.font = '500 ' + (10 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('Cadence: 142 BPM Speech Sync', -w / 2 + 16 * s, -h / 2 + 42 * s);

      const barCount = 15;
      const bw = (w - 36 * s) / (barCount * 1.5);
      const bg = bw * 0.5;
      const startX = -w / 2 + 18 * s;
      for (let i = 0; i < barCount; i++) {
        const maxBh = h * 0.42;
        const bh = (8 * s + maxBh * Math.sin(i * 0.45 + f) ** 2);
        roundRect(ctx, startX + i * (bw + bg), h / 2 - 12 * s - bh, bw, bh, 2 * s);
        ctx.fillStyle = i % 2 === 0 ? '#2997FF' : '#C6FF4A';
        ctx.fill();
      }
      ctx.restore();
    }

    function drawEditLayer(x, y, w, h, s, f) {
      ctx.save();
      ctx.translate(x, y);
      ctx.shadowColor = 'rgba(198, 255, 74, 0.3)';
      ctx.shadowBlur = 14 * s * f;

      roundRect(ctx, -w / 2, -h / 2, w, h, 14 * s);
      ctx.fillStyle = '#0C0F1A';
      ctx.fill();
      ctx.strokeStyle = '#C6FF4A';
      ctx.lineWidth = 2.5 * s;
      ctx.stroke();

      ctx.fillStyle = '#C6FF4A';
      ctx.font = '600 ' + (10 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('[05 / PACING & CUT VELOCITY]', -w / 2 + 16 * s, -h / 2 + 20 * s);

      const cuts = ['[0.0s HOOK]', '[0.8s CUT 1]', '[1.6s CUT 2]', '[2.4s PIVOT]'];
      const cxStep = (w - 32 * s) / 4;
      for (let i = 0; i < 4; i++) {
        const bx = -w / 2 + 16 * s + i * cxStep;
        roundRect(ctx, bx, -h / 2 + 30 * s, cxStep - 6 * s, 24 * s, 5 * s);
        ctx.fillStyle = '#161C2C';
        ctx.fill();
        ctx.fillStyle = '#F3F0E9';
        ctx.font = '500 ' + (9.5 * s) + 'px "IBM Plex Mono", monospace';
        ctx.fillText(cuts[i], bx + 4 * s, -h / 2 + 45 * s);
      }
      ctx.restore();
    }

    function drawContentDirection(x, y, w, h, s, assem) {
      ctx.save();
      ctx.translate(x, y);
      ctx.shadowColor = 'rgba(98, 87, 255, ' + (0.5 * assem) + ')';
      ctx.shadowBlur = 25 * s * assem;

      roundRect(ctx, -w / 2, -h / 2, w, h, 24 * s);
      ctx.fillStyle = '#F3F0E9';
      ctx.fill();
      ctx.strokeStyle = '#09090B';
      ctx.lineWidth = 4 * s;
      ctx.stroke();

      // Header
      roundRect(ctx, -w / 2 + 14 * s, -h / 2 + 14 * s, w - 28 * s, 68 * s, 14 * s);
      ctx.fillStyle = '#09090B';
      ctx.fill();

      ctx.fillStyle = '#C6FF4A';
      ctx.font = '600 ' + (10 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('[VIRALYST CONTENT DIRECTION]', -w / 2 + 28 * s, -h / 2 + 36 * s);

      ctx.fillStyle = '#F3F0E9';
      ctx.font = '700 ' + (18 * s) + 'px "Bricolage Grotesque", sans-serif';
      ctx.fillText('THE CONTRARIAN OPEN', -w / 2 + 28 * s, -h / 2 + 62 * s);

      roundRect(ctx, w / 2 - 130 * s, -h / 2 + 26 * s, 105 * s, 26 * s, 6 * s);
      ctx.fillStyle = '#6257FF';
      ctx.fill();
      ctx.fillStyle = '#F3F0E9';
      ctx.font = '600 ' + (10 * s) + 'px "IBM Plex Mono", monospace';
      ctx.fillText('READY TO SHOOT', w / 2 - 120 * s, -h / 2 + 43 * s);

      // 4 Operational Direction Modules
      const secH = (h - 130 * s) / 4;
      const specs = [
        { label: '01 / HOOK SCRIPT', desc: 'Why 99% of short-form hooks fail in the first 2 seconds.', badge: 'CONTRARIAN', col: '#FF3B45' },
        { label: '02 / FRAME PACING', desc: '0.8s micro-cuts with tactile visual proof before dialogue.', badge: 'VELOCITY', col: '#6257FF' },
        { label: '03 / AUDIO CADENCE', desc: '142 BPM rhythmic speech sync; seamless loop return.', badge: 'AUDIO MATCH', col: '#2997FF' },
        { label: '04 / CALL TO ACTION', desc: 'Comment trigger: Ask for disagreement to spark debate.', badge: 'RETENTION', col: '#FF2878' }
      ];

      for (let i = 0; i < 4; i++) {
        const sy = -h / 2 + 96 * s + i * (secH + 6 * s);
        roundRect(ctx, -w / 2 + 14 * s, sy, w - 28 * s, secH, 10 * s);
        ctx.fillStyle = '#E8E4DA';
        ctx.fill();

        ctx.fillStyle = specs[i].col;
        ctx.font = '700 ' + (11 * s) + 'px "Bricolage Grotesque", sans-serif';
        ctx.fillText(specs[i].label, -w / 2 + 26 * s, sy + 20 * s);

        ctx.fillStyle = '#09090B';
        ctx.font = (12 * s) + 'px "Instrument Sans", sans-serif';
        ctx.fillText(specs[i].desc, -w / 2 + 26 * s, sy + 42 * s);

        roundRect(ctx, w / 2 - 110 * s, sy + 10 * s, 85 * s, 20 * s, 5 * s);
        ctx.fillStyle = '#09090B';
        ctx.fill();
        ctx.fillStyle = specs[i].col;
        ctx.font = '600 ' + (9 * s) + 'px "IBM Plex Mono", monospace';
        ctx.fillText(specs[i].badge, w / 2 - 102 * s, sy + 23 * s);
      }
      ctx.restore();
    }

    function roundRect(ctx, x, y, width, height, radius) {
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.lineTo(x + width - radius, y);
      ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
      ctx.lineTo(x + width, y + height - radius);
      ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
      ctx.lineTo(x + radius, y + height);
      ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
      ctx.lineTo(x, y + radius);
      ctx.quadraticCurveTo(x, y, x + radius, y);
      ctx.closePath();
    }

    function handleResize() {
      if (isDestroyed) return;
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        if (isDestroyed) return;
        resizeCanvas();
        scheduleRender();
        ScrollTrigger.refresh();
      }, 150);
    }

    resizeCanvas();
    window.addEventListener('resize', handleResize);

    const finalTimeline = gsap.timeline({ paused: true });

    if (finalText) {
      const finalTextSplit = new SplitText(finalText, {
        type: 'words, chars',
        tag: 'span',
        charsClass: 'split-char',
        wordsClass: 'split-word'
      });

      gsap.set(finalTextSplit.words, { display: 'inline-block' });
      gsap.set(finalTextSplit.chars, {
        display: 'inline-block',
        opacity: 0,
        y: '0.3em'
      });

      finalTimeline.to(finalTextSplit.chars, {
        opacity: 1,
        y: '0em',
        ease: 'power3.out',
        duration: 0.5,
        stagger: 0.01
      });
    }

    if (buttons.length) {
      gsap.set(buttons, { y: '1em', opacity: 0 });
      finalTimeline.to(
        buttons,
        {
          y: '0em',
          opacity: 1,
          duration: 0.4,
          ease: 'power3.out',
          stagger: 0.1
        },
        '-=0.2'
      );
    }

    let finalState = 'before';

    const st = ScrollTrigger.create({
      trigger: wrap,
      start: startTrigger,
      end: endTrigger,
      scrub: 0.3,
      onUpdate: (self) => {
        if (isDestroyed) return;
        currentProgress = self.progress;
        scheduleRender();

        if (self.progress >= 0.68) {
          if (finalState !== 'played') {
            finalTimeline.timeScale(1.25).play();
            finalState = 'played';
          }
        } else {
          if (finalState !== 'before') {
            finalTimeline.timeScale(3).reverse();
            finalState = 'before';
          }
        }
      }
    });

    scheduleRender();

    boxSequenceDestroyFns.push(() => {
      isDestroyed = true;
      window.removeEventListener('resize', handleResize);
      st.kill();
      finalTimeline.kill();
    });
  });
}

let heroSequenceDestroyFns = [];

function destroyHeroSequence() {
  heroSequenceDestroyFns.forEach((fn) => fn());
  heroSequenceDestroyFns = [];
}

function initHeroSequence() {
  destroyHeroSequence();

  const wraps = nextPage.querySelectorAll('[data-hero-sequence]');
  const mm = gsap.matchMedia();

  heroSequenceDestroyFns.push(() => {
    mm.revert();
  });

  wraps.forEach((wrap) => {
    mm.add('(min-width: 992px)', () => {
      if (wrap.dataset.sequenceInit === 'true') return;
      wrap.dataset.sequenceInit = 'true';

      let isDestroyed = false;

      const element = wrap.querySelector('[data-hero-sequence-element]');
      const canvas = element && element.querySelector('[data-hero-sequence-canvas]');

      if (!element || !canvas) {
        delete wrap.dataset.sequenceInit;
        return;
      }

      const frames = parseInt(canvas.dataset.frames, 10) || 1;
      const digits = parseInt(canvas.dataset.digits, 10) || 3;
      const indexStart = parseInt(canvas.dataset.indexStart, 10) || 0;
      const desktopSrc = canvas.dataset.desktopSrc || '';
      const mobileSrc = canvas.dataset.mobileSrc || desktopSrc;
      const staticSrc = canvas.dataset.staticSrc;
      const filetype = canvas.dataset.filetype || 'webp';
      const startTrigger = wrap.dataset.scrollStart || 'top bottom';
      const endTrigger = 'bottom bottom';
      const fps = parseInt(canvas.dataset.fps, 10) || 24;
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      const isMobile = window.matchMedia('(max-width: 767px)').matches;
      const baseUrl = isMobile ? mobileSrc : desktopSrc;
      const lastIndex = indexStart + frames - 1;

      const ctx = canvas.getContext('2d');

      const loaded = new Map();
      const loading = new Set();
      const queue = [];

      let processingQueue = false;
      let resizeTimer;
      let currentFrame = indexStart;
      let tween = null;
      let lastDrawnFrame = -1;
      let st = null;
      let lastWindowWidth = window.innerWidth;

      const playhead = { frame: 0 };

      function resizeCanvas() {
        if (isDestroyed) return;

        const dpr = window.devicePixelRatio || 1;
        const width = element.clientWidth;
        const height = element.clientHeight;

        if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
          canvas.width = width * dpr;
          canvas.height = height * dpr;
          canvas.style.width = `${width}px`;
          canvas.style.height = `${height}px`;
        }
      }

      function drawCover(img) {
        if (!img || isDestroyed) return;

        const canvasWidth = canvas.width;
        const canvasHeight = canvas.height;
        const scale = Math.max(canvasWidth / img.width, canvasHeight / img.height);
        const x = (canvasWidth - img.width * scale) / 2;
        const y = (canvasHeight - img.height * scale) / 2;

        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        ctx.drawImage(img, x, y, img.width * scale, img.height * scale);
      }

      function handleResize() {
        if (isDestroyed) return;

        const newWidth = window.innerWidth;
        const widthChanged = newWidth !== lastWindowWidth;

        if (!widthChanged) return;

        lastWindowWidth = newWidth;

        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(() => {
          if (isDestroyed) return;

          resizeCanvas();
          if (loaded.size) drawImageAt(currentFrame);
          ScrollTrigger.refresh();
        }, 200);
      }

      function pad(num) {
        return String(num).padStart(digits, '0');
      }

      function getUrl(i) {
        return `${baseUrl}${pad(i)}.${filetype}`;
      }

      function loadFrame(i, onDone) {
        if (isDestroyed) return;
        if (loaded.has(i) || loading.has(i) || i < indexStart || i > lastIndex) return;

        const url = getUrl(i);
        loading.add(i);

        (async () => {
          try {
            if (isDestroyed) return;

            const res = await fetch(url);
            if (!res.ok) throw new Error(`HTTP ${res.status}`);

            if (isDestroyed) return;

            const blob = await res.blob();
            let asset;

            if (window.createImageBitmap) {
              asset = await createImageBitmap(blob, {
                imageOrientation: 'from-image'
              });
            } else {
              const img = new Image();
              const objectUrl = URL.createObjectURL(blob);

              try {
                img.src = objectUrl;

                if (img.decode) {
                  await img.decode();
                } else {
                  await new Promise((resolve, reject) => {
                    img.onload = resolve;
                    img.onerror = reject;
                  });
                }

                asset = img;
              } finally {
                URL.revokeObjectURL(objectUrl);
              }
            }

            if (isDestroyed) return;

            loaded.set(i, asset);

            if (typeof onDone === 'function') onDone();
          } catch (error) {
            if (!isDestroyed) {
              console.warn('[HeroSequence] Failed to load frame', {
                index: i,
                url,
                wrap,
                error
              });
            }
          } finally {
            loading.delete(i);
          }
        })();
      }

      function processQueue() {
        if (isDestroyed || processingQueue) return;

        const next = queue.shift();
        if (!next) return;

        processingQueue = true;

        const [a, b] = next;

        if (b - a <= 1) {
          processingQueue = false;
          processQueue();
          return;
        }

        const m = Math.floor((a + b) / 2);

        loadFrame(m, () => {
          if (isDestroyed) return;

          queue.push([a, m], [m, b]);
          processingQueue = false;
          setTimeout(processQueue, 0);
        });
      }

      function startLoading() {
        loadFrame(indexStart, () => {
          if (isDestroyed) return;

          drawImageAt(indexStart);
          loadFrame(lastIndex);
          queue.push([indexStart, lastIndex]);
          processQueue();
          ScrollTrigger.refresh();
        });
      }

      function findNearestLoaded(i) {
        for (let r = 1; r <= 10; r++) {
          if (loaded.has(i - r)) return i - r;
          if (loaded.has(i + r)) return i + r;
        }

        const keys = Array.from(loaded.keys());
        if (keys.length === 0) return null;

        let nearest = keys[0];
        let minDiff = Math.abs(i - nearest);

        for (const k of keys) {
          const diff = Math.abs(i - k);

          if (diff < minDiff) {
            nearest = k;
            minDiff = diff;
          }
        }

        return nearest;
      }

      function drawImageAt(i) {
        if (isDestroyed) return;

        const img = loaded.get(i);
        if (!img) return;

        currentFrame = i;
        drawCover(img);
      }

      function renderFrame(index) {
        if (isDestroyed) return;
        if (index === lastDrawnFrame) return;

        lastDrawnFrame = index;

        if (loaded.has(index)) {
          drawImageAt(index);
        } else {
          const nearest = findNearestLoaded(index);
          if (nearest !== null) drawImageAt(nearest);
        }
      }

      function startLoop() {
        if (isDestroyed) return;

        if (!tween) {
          tween = gsap.to(playhead, {
            frame: frames,
            duration: frames / fps,
            ease: 'none',
            repeat: -1,
            paused: true,
            onUpdate: () => {
              if (isDestroyed) return;

              const relativeIndex = Math.floor(playhead.frame) % frames;
              const index = indexStart + relativeIndex;

              renderFrame(index);
            }
          });
        }

        tween.play();
      }

      function stopLoop() {
        if (!tween) return;

        tween.pause();
      }

      function cleanup() {
        isDestroyed = true;

        delete wrap.dataset.sequenceInit;

        window.removeEventListener('resize', handleResize);
        clearTimeout(resizeTimer);

        if (tween) {
          tween.kill();
          tween = null;
        }

        if (st) {
          st.kill();
          st = null;
        }

        loaded.forEach((asset) => {
          if (asset && typeof asset.close === 'function') {
            asset.close();
          }
        });

        loaded.clear();
        loading.clear();
        queue.length = 0;

        ctx.clearRect(0, 0, canvas.width, canvas.height);
      }

      resizeCanvas();
      window.addEventListener('resize', handleResize);

      if (reduceMotion) {
        if (staticSrc) {
          const staticImage = new Image();

          staticImage.src = staticSrc;
          staticImage.onload = () => {
            if (!isDestroyed) drawCover(staticImage);
          };
        } else {
          loadFrame(indexStart, () => {
            drawImageAt(indexStart);
          });
        }

        return cleanup;
      }

      startLoading();

      st = ScrollTrigger.create({
        trigger: wrap,
        start: startTrigger,
        end: endTrigger,
        onEnter: () => startLoop(),
        onEnterBack: () => startLoop(),
        onLeave: () => stopLoop(),
        onLeaveBack: () => stopLoop()
      });

      return cleanup;
    });
  });
}

function initGenreInteraction() {
  const elements = nextPage.querySelectorAll("[data-genre-interaction]");

  elements.forEach((element) => {
    const list = element.querySelector("[data-genre-interaction-list]");
    const scope = element.querySelector("[data-genre-interaction-scope]");
    const items = element.querySelectorAll("[data-genre-interaction-item]");
    const boxes = element.querySelectorAll("[data-genre-interaction-box]");

    const itemPosCache = []
    const populateCache = () => {
      itemPosCache.length = 0
      const { left, top } = list.getBoundingClientRect()
      for (let i = 0; i < items.length; i++) {
        const item = items[i]
        item.dataset.index = i
        const { width, height, x, y } = item.getBoundingClientRect()
        itemPosCache.push({
          width,
          height,
          initialX: x,
          initialY: y,
          x: x - left,
          y: y - top,
        })
      }
    }

    populateCache();

    const effectCache = []
    const generateEffectCache = () => {
      for (let i = 0; i < items.length; i++) {
        const settings = []
        for (let b = 0; b < boxes.length; b++) {
          settings.push([gsap.utils.random(-15, 15), gsap.utils.random(-15, 15), gsap.utils
            .random(-12, 12)
          ])
        }
        effectCache.push(settings)
      }
    }

    generateEffectCache();

    window.addEventListener('resize', populateCache);

    let listBounds
    const setParallax = ({ x, y }) => {
      const { x: initialX, y: initialY, width, height } = listBounds
      for (let b = 0; b < boxes.length; b++) {
        boxes[b].style.setProperty('--px', (x - initialX) / width - 0.75)
        boxes[b].style.setProperty('--py', (y - initialY) / height - 0.75)
      }
    }

    const removeAnchor = async (event) => {
      if (event.target.tagName === 'LI') {
        const boxAnimations = boxes[0]
          .getAnimations()
          .filter((t) => t.transitionProperty === 'scale')
        await Promise.allSettled(boxAnimations.map((a) => a.finished))
        if (
          boxAnimations.length &&
          boxAnimations[0].playState === 'finished' &&
          getComputedStyle(boxes[0]).scale === '0'
        ) {

          element.dataset.startSet = 'false'
          element.style.removeProperty('--start-index')
          element.style.removeProperty('--start-width')
          scope.style.removeProperty('--active-index')
          scope.style.removeProperty('--active-offset')
          element.style.removeProperty('--translate-speed')

          element.dataset.activeParallax = 'false'
          list.style.removeProperty('--px')
          list.style.removeProperty('--py')
          listBounds = undefined
          list.removeEventListener('pointermove', setParallax, true)
        }
      }
    }

    let startIndex
    let startWidth
    const setAnchor = (event) => {
      if (event.target.tagName === 'LI') {
        const index = Number.parseInt(event.target.dataset.index, 10)

        const bounds = itemPosCache[index]
        if (element.dataset?.startSet !== 'true') {
          startIndex = index
          startWidth = bounds.width
          element.dataset.startSet = 'true'
          element.style.setProperty('--start-index', index)
          element.style.setProperty('--start-width', bounds.width)
        }
        scope.style.setProperty('--active-index', index - startIndex)
        scope.style.setProperty('--active-offset', bounds.width - startWidth)
        element.style.setProperty('--translate-speed', '0.2s')

        const tweaks = effectCache[index]
        for (let b = 0; b < boxes.length; b++) {
          boxes[b].style.setProperty('--x', gsap.utils.random(-15, 15))
          boxes[b].style.setProperty('--y', gsap.utils.random(-15, 15))
          boxes[b].style.setProperty('--r', gsap.utils.random(-15, 15))
        }

        element.dataset.activeParallax = 'true'
        listBounds = list.getBoundingClientRect()
        list.addEventListener('pointermove', setParallax, true)
      }
    }

    list.addEventListener('pointerenter', setAnchor, true);
    list.addEventListener('pointerleave', removeAnchor, true);
  })
}

function initFormValidation() {
  const forms = nextPage.querySelectorAll('[data-form-validate]');

  forms.forEach((form) => {
    const fields = form.querySelectorAll('[data-validate] input, [data-validate] textarea');
    const submitButtonDiv = form.querySelector(
      '[data-submit]'); // The div wrapping the submit button
    const submitInput = submitButtonDiv.querySelector(
      'input[type="submit"]'); // The actual submit button

    // Capture the form load time
    const formLoadTime = new Date().getTime(); // Timestamp when the form was loaded

    // Function to validate individual fields (input or textarea)
    const validateField = (field) => {
      const parent = field.closest('[data-validate]'); // Get the parent div
      const minLength = field.getAttribute('min');
      const maxLength = field.getAttribute('max');
      const type = field.getAttribute('type');
      let isValid = true;

      // Check if the field has content
      if (field.value.trim() !== '') {
        parent.classList.add('is--filled');
      } else {
        parent.classList.remove('is--filled');
      }

      // Validation logic for min and max length
      if (minLength && field.value.length < minLength) {
        isValid = false;
      }

      if (maxLength && field.value.length > maxLength) {
        isValid = false;
      }

      // Validation logic for email input type
      if (type === 'email' && !/\S+@\S+\.\S+/.test(field.value)) {
        isValid = false;
      }

      // Add or remove success/error classes on the parent div
      if (isValid) {
        parent.classList.remove('is--error');
        parent.classList.add('is--success');
      } else {
        parent.classList.remove('is--success');
        parent.classList.add('is--error');
      }

      return isValid;
    };

    // Function to start live validation for a field
    const startLiveValidation = (field) => {
      field.addEventListener('input', function () {
        validateField(field);
      });
    };

    // Function to validate and start live validation for all fields, focusing on the first field with an error
    const validateAndStartLiveValidationForAll = () => {
      let allValid = true;
      let firstInvalidField = null;

      fields.forEach((field) => {
        const valid = validateField(field);
        if (!valid && !firstInvalidField) {
          firstInvalidField = field; // Track the first invalid field
        }
        if (!valid) {
          allValid = false;
        }
        startLiveValidation(field); // Start live validation for all fields
      });

      // If there is an invalid field, focus on the first one
      if (firstInvalidField) {
        firstInvalidField.focus();
      }

      return allValid;
    };

    // Anti-spam: Check if form was filled too quickly
    const isSpam = () => {
      const currentTime = new Date().getTime();
      const timeDifference = (currentTime - formLoadTime) /
        1000; // Convert milliseconds to seconds
      return timeDifference < 5; // Return true if form is filled within 5 seconds
    };

    // Handle clicking the custom submit button
    submitButtonDiv.addEventListener('click', function () {
      // Validate the form first
      if (validateAndStartLiveValidationForAll()) {
        // Only check for spam after all fields are valid
        if (isSpam()) {
          alert('Form submitted too quickly. Please try again.');
          return; // Stop form submission
        }
        submitInput.click(); // Simulate a click on the <input type="submit">
      }
    });

    // Handle pressing the "Enter" key
    form.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' && event.target.tagName !== 'TEXTAREA') {
        event.preventDefault(); // Prevent the default form submission

        // Validate the form first
        if (validateAndStartLiveValidationForAll()) {
          // Only check for spam after all fields are valid
          if (isSpam()) {
            alert('Form submitted too quickly. Please try again.');
            return; // Stop form submission
          }
          submitInput.click(); // Trigger our custom form submission
        }
      }
    });
  });
}

function initTaglineCurve() {
  const elements = nextPage.querySelectorAll("[data-tagline-curve]");

  if (elements.length === 0) return;

  function getRadialTextFontSize(wrap, textEl, svgEl) {
    const textSizePx = parseFloat(getComputedStyle(textEl).fontSize) || 16;

    const viewBox = svgEl.viewBox && svgEl.viewBox.baseVal;
    const viewBoxWidth = viewBox && viewBox.width ? viewBox.width : svgEl.clientWidth || 1;
    const renderedWidth = svgEl.getBoundingClientRect().width || viewBoxWidth;

    const scale = renderedWidth / viewBoxWidth;

    return textSizePx / Math.max(scale, 0.001);
  }

  function updateTaglineCurve(element) {
    const svg = element.querySelector("[data-tagline-curve-svg]");
    const referenceText = element.querySelector("[data-tagline-curve-reference]");
    const svgText = element.querySelector("[data-tagline-curve-text]");

    if (!svg || !referenceText || !svgText) return;

    const fontSizePx = getRadialTextFontSize(element, referenceText, svg);

    svgText.setAttribute("font-size", `${fontSizePx}px`);
  }

  function getTextWidth(text) {
    const canvas = getTextWidth.canvas || (getTextWidth.canvas = document.createElement("canvas"))
    const context = canvas.getContext("2d")
    const computedStyle = window.getComputedStyle(document.querySelector('#textpath'))
    context.font = computedStyle.font

    return context.measureText(text).width
  }

  elements.forEach((element) => {
    updateTaglineCurve(element);

    const textPath = element.querySelector("[data-tagline-curve-svg] textPath");
    const text = textPath.textContent.trim();

    const textPathLength = getTextWidth(text) * 1.25;

    const pathLength = element.querySelector("[data-tagline-curve-svg] path").getTotalLength();
    const finalOffset = -(textPathLength * 100 / pathLength);

    gsap.to(textPath, {
      attr: { startOffset: finalOffset + "0%" },
      ease: 'none',
      scrollTrigger: {
        trigger: element,
        start: '-40% bottom',
        end: '60% top',
        scrub: 0.5
      }
    })

  });

  window.addEventListener("resize", () => {
    elements.forEach((element) => {
      updateTaglineCurve(element);
    });
  });
}

