function initMenu() {
  const menuToggle = document.querySelector("[data-menu-toggle]");
  const menu = document.querySelector("[data-menu]");
  const menuClose = menu ? menu.querySelector("[data-menu-close]") : null;
  const activeClass = "is--active";
  const hasMenuOpenClass = "has--menu-open";

  if (!menu || !menuClose || !menuToggle) return;
  if (menuToggle.dataset.menuInit === 'true') return;
  menuToggle.dataset.menuInit = 'true';

  menuToggle.addEventListener("click", toggle);
  menuClose.addEventListener("click", toggle);

  function onKeyDown(e) {
    if (e.key === "Escape") {
      e.preventDefault();
      menuClose.click();
    }
  }

  function toggle(e) { console.log("--- MENU TOGGLE CLICKED ---", e?.type);
    if (menu.classList.contains(activeClass)) {
      hide();
    } else {
      show();
    }
  }

  function show() {
    lenis.stop();
    window.addEventListener("keydown", onKeyDown);
    menu.classList.add(activeClass);
    document.documentElement.classList.add(hasMenuOpenClass);
  }

  function hide() {
    window.removeEventListener("keydown", onKeyDown);
    menu.classList.remove(activeClass);
    document.documentElement.classList.remove(hasMenuOpenClass);
    lenis.start();
  }
}

function initDetectScrollingDirection() {
  const thresholdTop = 50;
  const elements = document.querySelectorAll('[data-scrolling-started]');

  lenis.on('scroll', ({ scroll }) => {
    const started = scroll > thresholdTop;

    elements.forEach(el =>
      el.setAttribute('data-scrolling-started', started)
    );
  });
}

function initBackgroundAnimation() {
  const elements = nextPage.querySelectorAll("[data-background-animation]");

  elements.forEach((element) => {
    const paths = element.querySelectorAll("path");
    let mm = gsap.matchMedia();

    const isSmall = element.hasAttribute("data-background-animation-small");
    const strokeValue = isSmall ? 35 : 60;

    mm.add("(prefers-reduced-motion: no-preference)", () => {
      gsap.set(paths, {
        attr: { "stroke-width": 0 },
        rotate: 0,
        transformOrigin: "center center",
        transformBox: "fill-box",
      });

      const tl = gsap.timeline({ paused: true })
        .to(paths, {
          attr: { "stroke-width": strokeValue },
          rotate: 2,
          duration: 3,
          ease: "sine.inOut",
        })
        .to(paths, {
          attr: { "stroke-width": 0 },
          rotate: 0,
          duration: 3,
          ease: "sine.inOut",
        });

      tl.repeat(-1);

      ScrollTrigger.create({
        trigger: element,
        start: "top bottom",
        end: "bottom top",
        onEnter: () => tl.play(),
        onEnterBack: () => tl.play(),
        onLeave: () => tl.pause(),
        onLeaveBack: () => tl.pause(),
      });
    });
  });
}

function initCallout() {
  const elements = nextPage.querySelectorAll("[data-call-out]");

  elements.forEach((element) => {
    const cards = element.querySelectorAll("[data-call-out-item]");
    const cardContent = element.querySelectorAll("[data-call-out-child]");

    const container = element;
    const containerW = container.clientWidth;
    const cardsLength = cards.length;

    let currentPortion = 0;

    cards.forEach((card) => {
      gsap.set(card, {
        xPercent: (Math.random() - 0.5) * 10,
        yPercent: (Math.random() - 0.5) * 10,
        rotation: (Math.random() - 0.5) * 15,
      });
    });

    gsap.from(cards, {
      rotation: (Math.random() - 0.5) * 15,
      yPercent: "+=150",
      duration: 1.05,
      ease: 'elastic.out(1, 0.75)',
      stagger: 0.088,
      scrollTrigger: {
        trigger: element,
        start: "top 85%",
        once: true,
      },
    });

    container.addEventListener("mousemove", (e) => {
      const mouseX = e.clientX - container.getBoundingClientRect().left;
      const percentage = mouseX / containerW;
      const activePortion = Math.ceil(percentage * cardsLength);

      if (currentPortion !== activePortion && activePortion > 0 && activePortion <=
        cardsLength) {

        if (currentPortion !== 0) {
          resetPortion(currentPortion - 1);
        }

        currentPortion = activePortion;
        newPortion(currentPortion - 1);
      }
    });

    container.addEventListener("mouseleave", () => {
      if (currentPortion > 0) resetPortion(currentPortion - 1);
      currentPortion = 0;

      gsap.to(cardContent, {
        xPercent: 0,
        ease: 'elastic.out(1, 0.75)',
        duration: 0.85,
      });
    });

    function newPortion(i) {
      gsap.to(cards[i], {
        xPercent: 0,
        yPercent: 0,
        rotation: 0,
        duration: 0.85,
        scale: 1.075,
        ease: 'elastic.out(1, 0.75)',
      });

      cardContent.forEach((cardContent, index) => {
        if (index !== i) {
          gsap.to(cardContent, {
            xPercent: 45 / (index - i),
            ease: 'elastic.out(1, 0.75)',
            duration: 0.85,
          });
        } else {
          gsap.to(cardContent, {
            xPercent: 0,
            ease: 'elastic.out(1, 0.75)',
            duration: 0.85,
          });
        }
      });
    }

    function resetPortion(index) {
      const count = cards.length;

      gsap.to(cards[index], {
        xPercent: (Math.random() - 0.5) * 10,
        yPercent: (Math.random() - 0.5) * 10,
        rotation: (Math.random() - 0.5) * 20,
        scale: 1,
        duration: 0.85,
        ease: 'elastic.out(1, 0.75)',
      });
    }
  });
}

function initHandwrittenTextInview() {
  const elements = nextPage.querySelectorAll("[data-handwritten-text-inview]");

  elements.forEach((element) => {
    let mm = gsap.matchMedia();

    mm.add("(prefers-reduced-motion: no-preference)", () => {
      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: element,
          start: "top 95%",
        },
      });

      const textSplit = new SplitText(element, {
        type: "words, chars",
        tag: "span",
        charsClass: "split-char",
        wordsClass: "split-word",
      });

      gsap.set(textSplit.words, { display: "inline-block" })
      gsap.set(textSplit.chars, {
        display: "inline-block",
        opacity: 0,
        rotate: 22,
        x: "-0.25em",
        y: "0.5em"
      })

      tl.to(textSplit.chars, {
        opacity: 1,
        rotate: 0,
        x: "0em",
        y: "0em",
        ease: 'elastic.out(1, 0.75)',
        duration: 0.75,
        stagger: 0.016
      });
    });
  });
}

function initButtonAlt() {
  const buttons = nextPage.querySelectorAll("[data-button-alt]");

  let mm = gsap.matchMedia();

  buttons.forEach((element) => {
    mm.add("(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)",
      () => {
        const text = element.querySelector("[data-button-alt-text]");

        if (!text) return;

        const textSplit = new SplitText(text, {
          type: "chars",
          tag: "span",
          charsClass: "split-char",
        });

        const targets = [...textSplit.chars];

        gsap.set(targets, {
          display: "inline-block",
          transformOrigin: "center center",
          willChange: "transform"
        });

        const tl = gsap.timeline({
          paused: true,
        });

        tl.to(targets, {
          keyframes: {
            "0%": {
              yPercent: 0,
              scaleY: 1,
              rotate: 0,
            },
            "20%": {
              yPercent: 55,
              scaleY: 0.3,
              rotate: 17,
              ease: "power2.in",
            },
            "100%": {
              yPercent: 0,
              scaleY: 1,
              rotate: 0,
              ease: "elastic.out(1,0.4)",
            },
          },
          duration: 0.725,
          stagger: {
            amount: 0.225,
          },
        });

        const hoverRoot = element.closest("[data-hover]") || element;

        const pause = () => {
          tl.pause();

          gsap.to(targets, {
            yPercent: 0,
            scaleY: 1,
            rotate: 0,
            duration: 0.2,
            ease: "power2.out",
            overwrite: "auto",
          });
        };

        const onEnter = () => tl.restart();

        const onLeave = () => {
          pause();
        };

        const onFocusIn = () => {
          if (hoverRoot.matches(":focus-visible")) tl.restart();
        };

        const onFocusOut = () => {
          if (hoverRoot.matches(":hover")) return;
          pause();
        };

        hoverRoot.addEventListener("mouseenter", onEnter);
        hoverRoot.addEventListener("mouseleave", onLeave);
        hoverRoot.addEventListener("focusin", onFocusIn);
        hoverRoot.addEventListener("focusout", onFocusOut);

        return () => {
          hoverRoot.removeEventListener("mouseenter", onEnter);
          hoverRoot.removeEventListener("mouseleave", onLeave);
          hoverRoot.removeEventListener("focusin", onFocusIn);
          hoverRoot.removeEventListener("focusout", onFocusOut);
          tl.kill();
          textSplit.revert();
        };
      });
  });
}

